package net.jamesjennison.spoolio

import android.content.Context
import android.nfc.*
import android.nfc.tech.Ndef
import android.os.Handler
import android.os.Looper
import android.util.Base64
import androidx.compose.runtime.*
import net.jamesjennison.spoolio.core.*
import java.util.concurrent.Executors

class NfcCoordinator(context:Context) {
    private val machine=WriteStateMachine(); private val io=Executors.newSingleThreadExecutor(); private val main=Handler(Looper.getMainLooper())
    private val journal=WriteJournal(context)
    var state by mutableStateOf(machine.state); private set
    var lastRead by mutableStateOf<DecodeResult?>(null); private set
    var unresolvedArchiveCount by mutableIntStateOf(journal.archiveCount()); private set
    init { journal.load()?.let{machine.restoreUnknown(it.uid,it.payload);state=machine.state} }
    fun arm(intent:OpenSpoolIntent)=dispatch{machine.arm(intent)}
    fun approveOverwrite()=dispatch{machine.approveOverwrite()}
    fun cancel()=dispatch{machine.cancel();persistOrClear()}
    fun archiveUnknown()=dispatch{val s=machine.state;val uid=s.uid?:error("No unresolved tag");val payload=journal.activePayload()?:error("No unresolved payload");check(journal.archive(uid,payload)){"Could not archive unresolved write"};machine.archiveUnknown();journal.clear();main.post{unresolvedArchiveCount=journal.archiveCount()}}
    fun shutdown(){io.shutdown()}
    fun onTag(tag:Tag){ io.execute { handle(tag) } }
    private fun dispatch(block:()->Unit){io.execute{runCatching(block).onFailure{e->main.post{state=state.copy(detail=e.message?:"Operation rejected")}};publish()}}
    private fun publish(){val next=machine.state;main.post{state=next}}
    private fun persistOrClear(){val s=machine.state;when(s.phase){WritePhase.WRITING,WritePhase.VERIFYING,WritePhase.WRITE_OUTCOME_UNKNOWN->{val uid=s.uid;val payload=s.intent?.payload;if(uid!=null&&payload!=null)journal.save(uid,payload)}WritePhase.VERIFIED->journal.clear();else->Unit}}
    private fun awaitingWrite()=machine.state.phase in setOf(WritePhase.AWAITING_TAG,WritePhase.INSPECTING,WritePhase.NEEDS_OVERWRITE_CONSENT)
    private fun handle(tag:Tag){
        val ndef=Ndef.get(tag) ?: run {if(awaitingWrite()){machine.rejectBeforeWrite("Unsupported or unformatted tag. Automatic formatting is disabled.");publish()}else main.post{lastRead=DecodeResult.Rejected("Unsupported or unformatted tag. Automatic formatting is disabled.")};return}
        try {
            ndef.connect()
            val current=ndef.ndefMessage // active RF read; never cachedNdefMessage
            val records=current?.records?.map{TagRecord(it.tnf.toInt(),it.type.toString(Charsets.US_ASCII),it.payload)}?:emptyList()
            val snapshot=TagSnapshot(tag.id.copyOf(),ndef.isWritable,ndef.maxSize,records)
            if(machine.state.phase==WritePhase.VERIFYING||machine.state.phase==WritePhase.WRITE_OUTCOME_UNKNOWN){
                machine.reconciled(snapshot);persistOrClear();main.post{lastRead=decodeSingleOpenSpool(current)};publish();return
            }
            if(!awaitingWrite()){main.post{lastRead=decodeSingleOpenSpool(current)};return}
            val intent=machine.state.intent ?: return
            val message=NdefMessage(arrayOf(NdefRecord.createMime(OpenSpoolCodec.MIME,intent.payload)))
            val existingOpenSpool=current?.records?.filter{it.tnf==NdefRecord.TNF_MIME_MEDIA&&it.type.toString(Charsets.US_ASCII)==OpenSpoolCodec.MIME}.orEmpty()
            if(records.size>1||records.isNotEmpty()&&existingOpenSpool.size!=1){machine.rejectBeforeWrite("Existing tag content is ambiguous and will not be overwritten");publish();return}
            if(existingOpenSpool.size>1){machine.rejectBeforeWrite("Multiple OpenSpool records are ambiguous and will not be overwritten");publish();return}
            val unsupported=existingOpenSpool.map{OpenSpoolCodec.decode(it.payload)}.firstOrNull{it !is DecodeResult.Supported}
            if(unsupported!=null){val reason=when(unsupported){is DecodeResult.ReadOnly->unsupported.reason;is DecodeResult.Rejected->unsupported.reason;else->"Unsupported OpenSpool profile"};machine.rejectBeforeWrite("Existing OpenSpool content is read-only: $reason");publish();return}
            machine.inspected(snapshot,message.toByteArray().size);publish()
            if(machine.state.phase!=WritePhase.WRITING)return
            val writeUid=machine.state.uid;val writePayload=machine.state.intent?.payload
            if(writeUid==null||writePayload==null||!journal.save(writeUid,writePayload)){machine.writeFailedBeforeCall("Could not durably journal the write; no write was attempted");publish();return}
            try { ndef.writeNdefMessage(message) } catch(e:Exception){ machine.writeInterrupted("Write did not complete: ${e.javaClass.simpleName}");publish();return }
            machine.writeReturned();persistOrClear();publish()
            // This is an uncached RF read after write. Any loss leaves UNKNOWN.
            val fresh=ndef.ndefMessage
            val freshRecords=fresh?.records?.map{TagRecord(it.tnf.toInt(),it.type.toString(Charsets.US_ASCII),it.payload)}?:emptyList()
            machine.reconciled(TagSnapshot(tag.id.copyOf(),ndef.isWritable,ndef.maxSize,freshRecords));persistOrClear();main.post{lastRead=decodeSingleOpenSpool(fresh)};publish()
        } catch(e:Exception){
            if(machine.state.phase==WritePhase.WRITING||machine.state.phase==WritePhase.VERIFYING)machine.writeInterrupted("Tag connection lost")
            else if(machine.state.phase==WritePhase.WRITE_OUTCOME_UNKNOWN)machine.unknownReadFailed("NFC reconciliation read failed: ${e.javaClass.simpleName}")
            else if(awaitingWrite())machine.rejectBeforeWrite("NFC read failed: ${e.javaClass.simpleName}") else main.post{lastRead=DecodeResult.Rejected("NFC read failed: ${e.javaClass.simpleName}")}
            persistOrClear()
            publish()
        } finally { runCatching{ndef.close()} }
    }
    private fun decodeSingleOpenSpool(message:NdefMessage?):DecodeResult {val records=message?.records?:emptyArray();if(records.size!=1)return DecodeResult.Rejected("Expected exactly one OpenSpool NDEF record");val record=records.single();if(record.tnf!=NdefRecord.TNF_MIME_MEDIA||record.type.toString(Charsets.US_ASCII)!=OpenSpoolCodec.MIME)return DecodeResult.Rejected("No OpenSpool MIME record found");return OpenSpoolCodec.decode(record.payload)}
}

internal class WriteJournal(context:Context){
    data class Entry(val uid:ByteArray,val payload:ByteArray)
    private val prefs=context.getSharedPreferences("nfc-write-journal",Context.MODE_PRIVATE)
    fun save(uid:ByteArray,payload:ByteArray):Boolean=prefs.edit().putInt("version",1).putString("uid",Base64.encodeToString(uid,Base64.NO_WRAP)).putString("payload",Base64.encodeToString(payload,Base64.NO_WRAP)).commit()
    fun load():Entry?=runCatching{if(prefs.getInt("version",0)!=1)return null;val uid=Base64.decode(prefs.getString("uid",null)?:return null,Base64.DEFAULT);val payload=Base64.decode(prefs.getString("payload",null)?:return null,Base64.DEFAULT);if(uid.isEmpty()||payload.isEmpty())return null;Entry(uid,payload)}.getOrNull()
    fun activePayload():ByteArray?=load()?.payload
    fun archiveCount():Int=prefs.getInt("archive_count",0)
    fun archive(uid:ByteArray,payload:ByteArray):Boolean{val count=prefs.getInt("archive_count",0);check(count < Int.MAX_VALUE){"Unresolved archive capacity reached"};val slot=count;return prefs.edit().putInt("archive_count",count+1).putString("archive_$slot",System.currentTimeMillis().toString()+":"+Base64.encodeToString(uid,Base64.NO_WRAP)+":"+Base64.encodeToString(payload,Base64.NO_WRAP)).commit()}
    fun clear():Boolean=prefs.edit().remove("version").remove("uid").remove("payload").commit()
}

